Object.assign(SNIP,{"l33mem": "struct Vec {\n    double x, y;\n    Vec operator+(const Vec& o) const {      // a + b  ->  a.operator+(b)\n        return Vec{x + o.x, y + o.y};\n    }\n    Vec& operator+=(const Vec& o) {          // sửa chính đối tượng, trả về *this\n        x += o.x;\n        y += o.y;\n        return *this;\n    }\n    bool operator==(const Vec& o) const {\n        return x == o.x && y == o.y;\n    }\n};\nVec operator*(double k, const Vec& v) {      // 2 * v: vế trái là double nên phải là hàm ngoài lớp\n    return Vec{k * v.x, k * v.y};\n}", "l33out": "class PhanSo {\n    int tu, mau;\npublic:\n    PhanSo(int t, int m) : tu(t), mau(m) {}\n    friend ostream& operator<<(ostream& os, const PhanSo& p);\n};\n\nostream& operator<<(ostream& os, const PhanSo& p) {\n    os << p.tu << \"/\" << p.mau;\n    return os;                     // trả về chính luồng để viết nối tiếp\n}\ncout << PhanSo(1, 2) << \" va \" << PhanSo(3, 4) << \"\\n\";"});PRESET_NOTES["l33"]={"Ví dụ: Phân số với + và ==": "a + b gọi a.operator+(b) và trả về một PhanSo mới; c nhận chính đối tượng đó. cout << a gọi operator<<(cout, a). a + b + c tính từ trái: (a + b) + c. Phân số chưa được rút gọn: bài tập 1 sẽ làm việc đó.", "Ví dụ: Véc-tơ: +, +=, - một ngôi và 2 * v": "a += b sửa chính a và trả về tham chiếu *this. -a là toán tử một ngôi, không có tham số. 2 * b có vế trái là double nên operator* phải là hàm ngoài lớp. Struct Vec để thành viên public nên operator<< không cần friend.", "Ví dụ: operator< để sắp xếp": "sort không có hàm so sánh thì dùng operator< của phần tử. Ở đây “nhỏ hơn” được định nghĩa là: điểm cao hơn đứng trước, bằng điểm thì xếp theo tên. Binh đứng trước Chi vì cùng 8 điểm và B < C.", "Ví dụ: operator[] trả về tham chiếu": "m[2] gọi m.operator[](2) và nhận về tham chiếu tới a[2], nên gán và ++ tác động thẳng lên phần tử bên trong. Chỉ số sai được chặn lại thay vì ghi ra ngoài mảng. Đây cũng là cách vector::at() hoạt động.", "Lỗi: thiếu operator<< khi in đối tượng": "cout không biết in Diem: g++ báo no match for 'operator<<'. Viết ostream& operator<<(ostream& os, const Diem& d) { return os << d.x << ' ' << d.y; } hoặc in từng thành viên.", "Lỗi: quên return *this trong +=": "Hàm khai báo trả về Dem& nhưng không có return: g++ cảnh báo no return statement, và khi chạy tới cuối hàm chương trình bị dừng (Illegal instruction). Thêm return *this; ở cuối."};EX_HINTS["l33"]=[["Vì mẫu luôn dương, so sánh a/b < c/d tương đương a*d < c*b (nhân chéo không đổi chiều).", "Hàm tạo đã rút gọn nên hai phân số bằng nhau khi và chỉ khi tử bằng tử, mẫu bằng mẫu."], ["k * v có vế trái là số nên phải viết hàm ngoài lớp operator*(long long k, const Vec& v).", "v * k có thể viết bằng cách gọi lại k * v."], ["“Nhỏ hơn” ở đây nghĩa là “đứng trước”: hiệu số lớn hơn thì trả về true.", "So sánh lần lượt từng tiêu chí; chỉ khi tiêu chí trước bằng nhau mới xét tiêu chí sau."]];
/* ===================== BÀI 33 · Nạp chồng toán tử ===================== */
/* Bài 33 · Nạp chồng toán tử
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P33=[{label:"Ví dụ: Phân số với + và ==",input:"",code:"#include <iostream>\nusing namespace std;\n\nclass PhanSo {\n    int tu, mau;\npublic:\n    PhanSo(int t = 0, int m = 1) : tu(t), mau(m) {}\n    PhanSo operator+(const PhanSo& o) const {\n        return PhanSo(tu * o.mau + o.tu * mau, mau * o.mau);\n    }\n    bool operator==(const PhanSo& o) const {\n        return tu * o.mau == o.tu * mau;\n    }\n    friend ostream& operator<<(ostream& os, const PhanSo& p);\n};\n\nostream& operator<<(ostream& os, const PhanSo& p) {\n    os << p.tu << \"/\" << p.mau;\n    return os;\n}\n\nint main() {\n    PhanSo a(1, 2), b(1, 3);\n    PhanSo c = a + b;\n    cout << a << \" + \" << b << \" = \" << c << \"\\n\";\n    cout << (a == PhanSo(2, 4)) << \"\\n\";\n    cout << a + b + c << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Véc-tơ: +, +=, - một ngôi và 2 * v",input:"",code:"#include <iostream>\nusing namespace std;\n\nstruct Vec {\n    double x, y;\n    Vec operator+(const Vec& o) const {\n        return Vec{x + o.x, y + o.y};\n    }\n    Vec& operator+=(const Vec& o) {\n        x += o.x;\n        y += o.y;\n        return *this;\n    }\n    Vec operator-() const {\n        return Vec{-x, -y};\n    }\n};\n\nVec operator*(double k, const Vec& v) {\n    return Vec{k * v.x, k * v.y};\n}\n\nostream& operator<<(ostream& os, const Vec& v) {\n    return os << \"(\" << v.x << \", \" << v.y << \")\";\n}\n\nint main() {\n    Vec a{1, 2}, b{3, -1};\n    cout << a + b << \"\\n\";\n    a += b;\n    a += b;\n    cout << a << \" \" << -a << \"\\n\";\n    cout << 2 * b << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: operator< để sắp xếp",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nstruct SinhVien {\n    string ten;\n    int diem;\n    bool operator<(const SinhVien& o) const {\n        if (diem != o.diem) return diem > o.diem;\n        return ten < o.ten;\n    }\n};\n\nint main() {\n    vector<SinhVien> ds = {{\"Chi\", 8}, {\"An\", 9}, {\"Binh\", 8}, {\"Dung\", 7}};\n    sort(ds.begin(), ds.end());\n    for (const SinhVien& s : ds) cout << s.ten << \" \" << s.diem << \"\\n\";\n    return 0;\n}"},{label:"Ví dụ: operator[] trả về tham chiếu",input:"",code:"#include <iostream>\nusing namespace std;\n\nclass MangAnToan {\n    int a[5];\npublic:\n    MangAnToan() {\n        for (int i = 0; i < 5; i++) a[i] = 0;\n    }\n    int& operator[](int i) {\n        if (i < 0 || i >= 5) {\n            cout << \"Chi so \" << i << \" ngoai mang, dung o 0\\n\";\n            return a[0];\n        }\n        return a[i];\n    }\n};\n\nint main() {\n    MangAnToan m;\n    m[2] = 7;\n    m[2]++;\n    m[10] = 3;\n    cout << m[2] << \" \" << m[0] << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: thiếu operator<< khi in đối tượng",input:"",code:"#include <iostream>\nusing namespace std;\n\nstruct Diem {\n    int x, y;\n};\n\nint main() {\n    Diem a{1, 2};\n    cout << a << \"\\n\";\n    return 0;\n}"},{label:"Lỗi: quên return *this trong +=",input:"",code:"#include <iostream>\nusing namespace std;\n\nstruct Dem {\n    int n = 0;\n    Dem& operator+=(int k) {\n        n += k;\n    }\n};\n\nint main() {\n    Dem d;\n    d += 5;\n    cout << d.n << \"\\n\";\n    return 0;\n}"}];
const sim33=makeSim2(document.getElementById("sim-l33"),{id:"s33",presets:P33});
makeEx2(document.getElementById("ex-l33"),sim33,[{t:"Phân số rút gọn: cộng và so sánh",d:"Viết lớp <code>PhanSo<\/code> có hàm tạo tự rút gọn (mẫu luôn dương), <code>operator+<\/code>, <code>operator&lt;<\/code>, <code>operator==<\/code> và hàm friend <code>operator&lt;&lt;<\/code> in <code>t/m<\/code> (in <code>t<\/code> nếu mẫu bằng 1). Nhập hai phân số a b c d (b, d ≠ 0, các số trong khoảng ±1000). In tổng, rồi in <code>&lt;<\/code>, <code>&gt;<\/code> hoặc <code>=<\/code> khi so sánh phân số thứ nhất với thứ hai.",tests:[{in:"1 2 1 3",out:"5/6\n>"},{in:"1 4 3 4",out:"1\n<"},{in:"2 -4 -1 2",out:"-1\n="},{in:"0 5 3 1",out:"3\n<"}],start:"#include <iostream>\nusing namespace std;\n\nint ucln(int a, int b) {\n    if (a < 0) a = -a;\n    if (b < 0) b = -b;\n    while (b) {\n        int r = a % b;\n        a = b;\n        b = r;\n    }\n    return a;\n}\n\nclass PhanSo {\n    int tu, mau;\npublic:\n    PhanSo(int t, int m) : tu(t), mau(m) {\n        // rút gọn, mẫu dương\n    }\n    // operator+, operator<, operator==\n    friend ostream& operator<<(ostream& os, const PhanSo& p);\n};\n\nostream& operator<<(ostream& os, const PhanSo& p) {\n    // in t/m, hoặc t nếu m == 1\n    return os;\n}\n\nint main() {\n    int a, b, c, d;\n    cin >> a >> b >> c >> d;\n    PhanSo x(a, b), y(c, d);\n    cout << x + y << \"\\n\";\n    if (x < y) cout << \"<\\n\";\n    else if (x == y) cout << \"=\\n\";\n    else cout << \">\\n\";\n    return 0;\n}",need:/operator\s*\+[\s\S]*operator\s*<\s*\([\s\S]*operator\s*==[\s\S]*ostream\s*&\s*operator\s*<<\s*\(/,needMsg:"Hãy viết operator+, operator<, operator== và ostream& operator<<."},{t:"Véc-tơ hai chiều",d:"Viết <code>struct Vec { long long x, y; }<\/code> với <code>operator+<\/code>, <code>operator-<\/code> (hai ngôi), <code>operator*<\/code> giữa số nguyên và Vec (cả <code>k * v<\/code> lẫn <code>v * k<\/code>) và hàm thành viên <code>long long tichVoHuong(const Vec&amp;) const<\/code>. Nhập x1 y1 x2 y2 k (trị tuyệt đối ≤ 10<sup>6<\/sup>). In a + b, a − b, k * a, b * k (dạng <code>(x, y)<\/code>, mỗi kết quả một dòng) rồi tích vô hướng a·b.",tests:[{in:"1 2 3 4 2",out:"(4, 6)\n(-2, -2)\n(2, 4)\n(6, 8)\n11"},{in:"0 0 5 -5 -1",out:"(5, -5)\n(-5, 5)\n(0, 0)\n(-5, 5)\n0"},{in:"1000000 1000000 1000000 -1000000 1000000",out:"(2000000, 0)\n(0, 2000000)\n(1000000000000, 1000000000000)\n(1000000000000, -1000000000000)\n0"}],start:"#include <iostream>\nusing namespace std;\n\nstruct Vec {\n    long long x, y;\n    // operator+, operator-, tichVoHuong\n};\n\n// operator* cho k * v và v * k\n\nostream& operator<<(ostream& os, const Vec& v) {\n    return os << \"(\" << v.x << \", \" << v.y << \")\";\n}\n\nint main() {\n    Vec a, b;\n    long long k;\n    cin >> a.x >> a.y >> b.x >> b.y >> k;\n    cout << a + b << \"\\n\" << a - b << \"\\n\" << k * a << \"\\n\" << b * k << \"\\n\";\n    cout << a.tichVoHuong(b) << \"\\n\";\n    return 0;\n}",need:/Vec\s+operator\s*\*\s*\(\s*long\s+long\s+\w+\s*,\s*const\s+Vec\s*&\s*\w+\s*\)[\s\S]*Vec\s+operator\s*\*\s*\(\s*const\s+Vec\s*&\s*\w+\s*,\s*long\s+long\s+\w+\s*\)/,needMsg:"Hãy viết cả hai hàm ngoài lớp: Vec operator*(long long k, const Vec& v) và Vec operator*(const Vec& v, long long k)."},{t:"Sắp xếp đội bóng",d:"Nhập n (1 ≤ n ≤ 1000) rồi n dòng: tên đội (không dấu cách), số bàn thắng, số bàn thua. Viết <code>struct Doi<\/code> có <code>bool operator&lt;(const Doi&amp;) const<\/code>: hiệu số (thắng − thua) cao hơn đứng trước; bằng hiệu số thì nhiều bàn thắng hơn đứng trước; vẫn bằng thì tên theo thứ tự từ điển. Dùng <code>sort(v.begin(), v.end())<\/code> rồi in tên các đội theo thứ tự, mỗi tên một dòng.",tests:[{in:"3\nA 5 2\nB 4 1\nC 2 0",out:"A\nB\nC"},{in:"2\nZed 1 1\nAce 1 1",out:"Ace\nZed"},{in:"4\nP 0 3\nQ 3 0\nR 10 7\nS 1 1",out:"R\nQ\nS\nP"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nstruct Doi {\n    string ten;\n    int thang, thua;\n    // bool operator<(const Doi& o) const { ... }\n};\n\nint main() {\n    int n;\n    cin >> n;\n    vector<Doi> v(n);\n    for (Doi& d : v) cin >> d.ten >> d.thang >> d.thua;\n    sort(v.begin(), v.end());\n    for (const Doi& d : v) cout << d.ten << \"\\n\";\n    return 0;\n}",need:/bool\s+operator\s*<\s*\(\s*const\s+Doi\s*&\s*\w+\s*\)\s*const[\s\S]*sort\s*\(\s*v\.begin\(\)\s*,\s*v\.end\(\)\s*\)/,needMsg:"Hãy viết bool operator<(const Doi& o) const trong struct Doi và gọi sort(v.begin(), v.end()) không kèm hàm so sánh."}]);

makeQuiz("quiz33","score33",[{"q": "Khi a là đối tượng và có hàm thành viên <code>operator+<\/code>, biểu thức <code>a + b<\/code> được dịch thành gì?", "o": ["<code>operator+(b, a)<\/code>", "<code>a.operator+(b)<\/code>", "<code>b.operator+(a)<\/code>", "<code>a = a + b<\/code>"], "a": 1, "e": "Toán tử thành viên được gọi trên vế trái, vế phải là đối số."}, {"q": "Vì sao <code>operator&lt;&lt;<\/code> để in bằng cout phải là hàm ngoài lớp?", "o": ["Vì hàm thành viên không in được", "Vì vế trái là cout (kiểu ostream), không phải đối tượng của lớp", "Vì phải là friend", "Vì cout là hằng"], "a": 1, "e": "Toán tử thành viên luôn có vế trái là đối tượng của lớp; cout << p có vế trái là ostream."}, {"q": "<code>operator+=<\/code> nên trả về gì?", "o": ["void", "Một bản sao mới", "Tham chiếu tới chính đối tượng (*this)", "bool"], "a": 2, "e": "+= sửa vế trái; trả về *this theo tham chiếu để viết nối tiếp như với số."}, {"q": "Có <code>bool operator&lt;(const T&amp;) const<\/code> trong lớp T. Điều gì dùng được ngay?", "o": ["cout &lt;&lt; t", "sort(v.begin(), v.end()) với vector&lt;T&gt;", "t1 == t2", "t1 + t2"], "a": 1, "e": "sort mặc định so sánh phần tử bằng <."}]);

